const crypto = require('crypto');

// Same scheme as convex/lib/signature.ts: t=<unix>,v1=hmac_sha256("<t>.<METHOD>.<path>.<body>")
function sign(method, path, body) {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const t = Math.floor(Date.now() / 1000);
  const mac = crypto.createHmac('sha256', secret).update(`${t}.${method}.${path}.${body}`).digest('hex');
  return `t=${t},v1=${mac}`;
}

const { execution, trigger, workflow } = $input.first().json;

// Metadata only. Provider errors can quote addresses, so those are scrubbed before they leave n8n.
const raw = execution?.error?.message || trigger?.error?.message || 'Unknown workflow error';
const message = String(raw).replace(/[^\s@]+@[^\s@]+/g, '[redacted]').slice(0, 300);
const executionId = String(execution?.id || `trigger-${workflow?.id}-${Date.now()}`);

const report = { executionId, workflow: workflow?.name || 'Unknown workflow', message };
if (execution?.lastNodeExecuted) report.node = execution.lastNodeExecuted;

const body = JSON.stringify(report);
return [{ json: { body, signature: sign('POST', '/n8n/workflow-failures', body), report } }];

// The last line of defense: this reaches the container logs even if Convex can't be reached.
const { report } = $('Build Failure Report').first().json;
const stored = !$json.error;
console.error(JSON.stringify({ type: 'lendloop.workflow.failed', storedInConvex: stored, ...report }));
return [{ json: { stored } }];
